{"code": "import pytest
import impl


class TestBasicAuthorization:
    def test_simple_allow(self):
        """Simple ALLOW case"""
        request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file.txt'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'read', 'resource': 'file.txt'}]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_simple_deny(self):
        """Simple DENY case"""
        request = {'subject': 'alice', 'roles': [], 'action': 'delete', 'resource': 'file.txt'}
        policies = [{'effect': 'DENY', 'principal': 'user:alice', 'action': 'delete', 'resource': '*'}]
        assert impl.authorize(request, policies) == 'DENY'

    def test_default_deny_no_matching_policy(self):
        """No matching policy defaults to DENY"""
        request = {'subject': 'bob', 'roles': [], 'action': 'write', 'resource': 'file.txt'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'read', 'resource': 'file.txt'}]
        assert impl.authorize(request, policies) == 'DENY'

    def test_deny_overrides_allow_regardless_of_order(self):
        """DENY takes precedence over ALLOW regardless of position"""
        request = {'subject': 'alice', 'roles': ['contractor'], 'action': 'read', 'resource': 'docs/reports/Q1.pdf'}
        policies = [
            {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'read', 'resource': 'docs/reports/*'},
            {'effect': 'DENY', 'principal': 'role:contractor', 'action': 'read', 'resource': 'docs/reports/*'}
        ]
        assert impl.authorize(request, policies) == 'DENY'


class TestPrincipalMatching:
    def test_principal_matching_wildcard_user_role(self):
        """Principal matching: wildcard, user:, role:"""
        # Wildcard matches any principal
        request = {'subject': 'anyone', 'roles': [], 'action': 'read', 'resource': 'file'}
        policies = [{'effect': 'ALLOW', 'principal': '*', 'action': 'read', 'resource': 'file'}]
        assert impl.authorize(request, policies) == 'ALLOW'

        # user: matches exact subject
        request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'read', 'resource': 'file'}]
        assert impl.authorize(request, policies) == 'ALLOW'

        # user: doesn't prefix-match
        policies = [{'effect': 'ALLOW', 'principal': 'user:al', 'action': 'read', 'resource': 'file'}]
        assert impl.authorize(request, policies) == 'DENY'

        # role: matches when role in list
        request = {'subject': 'alice', 'roles': ['contractor'], 'action': 'read', 'resource': 'file'}
        policies = [{'effect': 'ALLOW', 'principal': 'role:contractor', 'action': 'read', 'resource': 'file'}]
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_principal_case_sensitive_and_literal(self):
        """Principal patterns are case-sensitive and literal"""
        # Case-sensitive user
        request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}
        policies = [{'effect': 'ALLOW', 'principal': 'user:Alice', 'action': 'read', 'resource': 'file'}]
        assert impl.authorize(request, policies) == 'DENY'

        # Principal patterns are literal, not wildcards (user:al* does not match alice)
        policies = [{'effect': 'ALLOW', 'principal': 'user:al*', 'action': 'read', 'resource': 'file'}]
        assert impl.authorize(request, policies) == 'DENY'

        # Case-sensitive role
        request = {'subject': 'alice', 'roles': ['Contractor'], 'action': 'read', 'resource': 'file'}
        policies = [{'effect': 'ALLOW', 'principal': 'role:contractor', 'action': 'read', 'resource': 'file'}]
        assert impl.authorize(request, policies) == 'DENY'


class TestActionResourcePatterns:
    def test_pattern_matching_basics(self):
        """Action and resource patterns: wildcard, trailing *, exact match"""
        # Wildcard matches anything
        request = {'subject': 'alice', 'roles': [], 'action': 'delete', 'resource': 'anything'}
        policies = [
            {'effect': 'ALLOW', 'principal': 'user:alice', 'action': '*', 'resource': '*'}
        ]
        assert impl.authorize(request, policies) == 'ALLOW'

        # Exact match without wildcards
        request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file.txt'}
        policies = [
            {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'read', 'resource': 'file.txt'}
        ]
        assert impl.authorize(request, policies) == 'ALLOW'

        # Trailing * is prefix match (s3:Get* matches s3:GetObject)
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'file'}
        policies = [
            {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:Get*', 'resource': 'file'}
        ]
        assert impl.authorize(request, policies) == 'ALLOW'

        # s3:Get* also matches bare s3:Get
        request = {'subject': 'alice', 'roles': [], 'action': 's3:Get', 'resource': 'file'}
        assert impl.authorize(request, policies) == 'ALLOW'

    def test_pattern_edge_cases(self):
        """Pattern edge cases: no false prefix match, non-final *, case-sensitivity"""
        # docs/reports/* doesn't match docs/reportsQ1 (no separator)
        request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'docs/reportsQ1'}
        policies = [
            {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'read', 'resource': 'docs/reports/*'}
        ]
        assert impl.authorize(request, policies) == 'DENY'

        # Non-final * is literal (s3:*Object doesn't match s3:GetObject)
        request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'file'}
        policies = [
            {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:*Object', 'resource': 'file'}
        ]
        assert impl.authorize(request, policies) == 'DENY'

        # But s3:*Object does match literal s3:*Object
        request = {'subject': 'alice', 'roles': [], 'action': 's3:*Object', 'resource': 'file'}
        assert impl.authorize(request, policies) == 'ALLOW'

        # Case-sensitive matching
        request = {'subject': 'alice', 'roles': [], 'action': 'Read', 'resource': 'File'}
        policies = [
            {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'read', 'resource': 'file'}
        ]
        assert impl.authorize(request, policies) == 'DENY'


class TestValidation:
    def test_request_validation(self):
        """Request must have subject, roles (as list), action, resource"""
        # Missing subject
        with pytest.raises(ValueError, match="subject"):
            impl.authorize({'roles': [], 'action': 'read', 'resource': 'file'}, [])

        # Missing roles
        with pytest.raises(ValueError, match="roles"):
            impl.authorize({'subject': 'alice', 'action': 'read', 'resource': 'file'}, [])

        # Missing action
        with pytest.raises(ValueError, match="action"):
            impl.authorize({'subject': 'alice', 'roles': [], 'resource': 'file'}, [])

        # Missing resource
        with pytest.raises(ValueError, match="resource"):
            impl.authorize({'subject': 'alice', 'roles': [], 'action': 'read'}, [])

        # roles not a list
        with pytest.raises(ValueError, match="roles.*list"):
            impl.authorize({'subject': 'alice', 'roles': 'contractor', 'action': 'read', 'resource': 'file'}, [])

    def test_policy_validation(self):
        """Policy must have effect (ALLOW or DENY), principal, action, resource"""
        request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}

        # Missing effect
        with pytest.raises(ValueError, match="effect"):
            impl.authorize(request, [{'principal': '*', 'action': 'read', 'resource': 'file'}])

        # Missing principal
        with pytest.raises(ValueError, match="principal"):
            impl.authorize(request, [{'effect': 'ALLOW', 'action': 'read', 'resource': 'file'}])

        # Missing action
        with pytest.raises(ValueError, match="action"):
            impl.authorize(request, [{'effect': 'ALLOW', 'principal': '*', 'resource': 'file'}])

        # Missing resource
        with pytest.raises(ValueError, match="resource"):
            impl.authorize(request, [{'effect': 'ALLOW', 'principal': '*', 'action': 'read'}])

        # Invalid effect (case-sensitive)
        with pytest.raises(ValueError, match="Allow"):
            impl.authorize(request, [{'effect': 'Allow', 'principal': '*', 'action': 'read', 'resource': 'file'}])

        # Invalid effect typo
        with pytest.raises(ValueError, match="PERMIT"):
            impl.authorize(request, [{'effect': 'PERMIT', 'principal': '*', 'action': 'read', 'resource': 'file'}])

    def test_validation_before_matching(self):
        """Validation happens before matching (even for policies that wouldn't match)"""
        request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}
        # Invalid policy for different user still raises
        with pytest.raises(ValueError, match="WRONG"):
            impl.authorize(request, [{'effect': 'WRONG', 'principal': 'user:bob', 'action': 'write', 'resource': 'other'}])


class TestEdgeCases:
    def test_empty_policies_default_deny(self):
        """Empty policies list defaults to DENY"""
        request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}
        assert impl.authorize(request, []) == 'DENY'

    def test_multiple_roles(self):
        """Request with multiple roles; policy matches if one role matches"""
        request = {'subject': 'alice', 'roles': ['user', 'contractor'], 'action': 'read', 'resource': 'file'}
        policies = [
            {'effect': 'ALLOW', 'principal': 'role:contractor', 'action': 'read', 'resource': 'file'}
        ]
        assert impl.authorize(request, policies) == 'ALLOW'

        # None of the roles match
        request = {'subject': 'alice', 'roles': ['user', 'admin'], 'action': 'read', 'resource': 'file'}
        policies = [
            {'effect': 'ALLOW', 'principal': 'role:contractor', 'action': 'read', 'resource': 'file'}
        ]
        assert impl.authorize(request, policies) == 'DENY'

    def test_no_mutations(self):
        """Request and policies are not mutated"""
        request = {'subject': 'alice', 'roles': ['contractor'], 'action': 'read', 'resource': 'file'}
        request_copy = {'subject': 'alice', 'roles': ['contractor'], 'action': 'read', 'resource': 'file'}
        policies = [{'effect': 'ALLOW', 'principal': '*', 'action': '*', 'resource': '*'}]
        policies_copy = [{'effect': 'ALLOW', 'principal': '*', 'action': '*', 'resource': '*'}]

        impl.authorize(request, policies)

        assert request == request_copy
        assert policies == policies_copy
